class Solution {
  public int compareBitonicSums(int[] nums) {
    int n = nums.length, peak = 0;
    while (peak + 1 < n && nums[peak + 1] > nums[peak]) peak++;
    long asc = 0, desc = 0;
    for (int i = 0; i <= peak; i++) asc += nums[i];
    for (int i = peak; i < n; i++) desc += nums[i];
    return asc > desc ? 0 : asc < desc ? 1 : -1;
  }
}
